// План specs/admin-coupons.md 2.8 (кейс CP-12). Пользователь wojeg27104 (auth/user.json), десктоп, EN.
// @prod-safe: только Check; «Continue to payment» НЕ нажимается, переход на checkout.stripe.com обрывается.
// Нужен действующий купон для wojeg: код в переменной QA_COUPON_VALID (Active, «для wojeg» или «Anyone with the code», % скидка).
// На 19.10 все QA-купоны отключены → без переменной тест пропускается; путь до Stripe Checkout — только вручную (CP-14).
import { test, expect } from '../../fixtures';
import { CHECK_ERRORS, blockCouponWrites, checkCoupon, expectNoCouponWrites, startUserEn } from './coupon-helpers';

const VALID = process.env.QA_COUPON_VALID ?? '';

test('Billing coupon Check: valid coupon shows code, old price struck through, lower new price and "Continue to payment" (not clicked) #a10206 #b93722 @desktop @prod-safe', async ({ asUser }) => {
  test.skip(!VALID, 'нет действующего купона для wojeg — задать QA_COUPON_VALID=<код> (создаёт админ вручную, CP-14)');
  const page = await asUser('user');
  await startUserEn(page);
  const writes = await blockCouponWrites(page);
  await checkCoupon(page, VALID);
  // Источник: #291f7a9d п.1 — после Check цена до/после и «Continue to payment»; ручная проверка 19.10: $49 → $39.20 (r1-s3-pct-check).
  for (const e of Object.values(CHECK_ERRORS)) await expect(page.getByText(e, { exact: true })).toHaveCount(0);
  const pay = page.getByRole('button', { name: 'Continue to payment', exact: true });
  await expect(pay).toBeVisible();
  await expect(pay).toBeEnabled();
  const box = page.locator('div').filter({ has: pay }).filter({ hasText: VALID.toUpperCase() }).last();
  await expect(box).toContainText(/off/);
  await expect(box).toContainText('The discount is applied at checkout.');
  const old = box.locator('s, del, [style*="line-through"], .line-through').first();
  await expect(old, 'старая цена зачёркнута').toBeVisible();
  const oldPrice = Number((await old.innerText()).replace(/[^\d.]/g, ''));
  const prices = ((await box.innerText()).match(/\$\s?\d+(?:\.\d+)?/g) ?? []).map((p) => Number(p.replace(/[^\d.]/g, '')));
  expect(prices.length, 'две цены: до и после').toBeGreaterThanOrEqual(2);
  expect(Math.min(...prices), 'цена после скидки ниже старой').toBeLessThan(oldPrice);
  expectNoCouponWrites(writes);
});
